use crate::aap::caps::notifier;
use crate::aap::caps::types::{Category, Importance, ItemVerdict};

struct Node;

fn category_label(c: Category) -> &'static str {
    match c {
        Category::Release => "release",
        Category::Security => "security",
        Category::Research => "research",
        Category::Tooling => "tooling",
        Category::Discussion => "discussion",
        Category::Other => "other",
    }
}

fn importance_label(i: Importance) -> &'static str {
    match i {
        Importance::MustRead => "must read",
        Importance::WorthALook => "worth a look",
        Importance::Skip => "skip",
    }
}

fn importance_rank(i: Importance) -> u8 {
    match i {
        Importance::MustRead => 0,
        Importance::WorthALook => 1,
        Importance::Skip => 2,
    }
}

fn one_line(s: &str) -> String {
    s.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn render_entry(out: &mut String, e: &ItemVerdict) {
    out.push_str("- [");
    out.push_str(importance_label(e.importance));
    out.push_str(" / ");
    out.push_str(category_label(e.category));
    out.push_str("] ");
    let title = one_line(&e.title);
    if title.is_empty() {
        out.push_str("(untitled)");
    } else {
        out.push_str(&title);
    }
    if !e.feed.is_empty() {
        out.push_str(" (");
        out.push_str(&one_line(&e.feed));
        out.push(')');
    }
    out.push('\n');
    if !e.link.is_empty() {
        out.push_str("  ");
        out.push_str(&one_line(&e.link));
        out.push('\n');
    }
    let summary = e.summary.trim();
    if !summary.is_empty() {
        out.push_str("  ");
        out.push_str(&one_line(summary));
        out.push('\n');
    }
}

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let mut message = String::new();
        message.push_str("Digest for ");
        message.push_str(&composed.date);
        message.push('\n');

        let overview = composed.overview.trim();
        if !overview.is_empty() {
            message.push('\n');
            message.push_str(overview);
            message.push('\n');
        }

        let mut entries: Vec<&ItemVerdict> = composed.entries.iter().collect();
        entries.sort_by_key(|e| importance_rank(e.importance));

        message.push('\n');
        if entries.is_empty() {
            message.push_str("No items made the digest today.\n");
        } else {
            for e in entries {
                render_entry(&mut message, e);
            }
        }

        message.push_str(&format!(
            "\n{} item(s) considered.\n",
            composed.considered.len()
        ));

        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
